mapper.select:
SELECT `id`, `name`, `category`, `kcal`, `carbs`, `protein`, `fat`, `fiber`, `unit`, `approxUnit`, `userId`, `isDeleted`, `createdAt`, `updatedAt`
FROM `Ingredients`
WHERE `id` = #{id}
  AND `userId` = #{userId}
  AND `isDeleted` = 0
LIMIT 1

mapper.update:
UPDATE `Ingredients`
SET `isDeleted` = 1,
    `updatedAt` = CURRENT_TIMESTAMP
WHERE `id` = #{id}
  AND `userId` = #{userId}
  AND `isDeleted` = 0
